import{_ as n,l as i,o as e,c as l,v as r,p as s,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"预编译与计划缓存","description":"","frontmatter":{"title":"预编译与计划缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prepared-plan-cache.md","filePath":"cs/prepared-plan-cache.md","lastUpdated":1789023840000}'),c={name:"cs/prepared-plan-cache.md"};function h(A,a,m,_,P,T){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="预编译与计划缓存" tabindex="-1">预编译与计划缓存 <a class="header-anchor" href="#预编译与计划缓存" aria-label="Permalink to &quot;预编译与计划缓存&quot;">​</a></h1><div class="epigraph"><p>语句先解析、绑定类型、优化成计划；同一形状反复出现时，缓存计划摊掉优化，也可能把第一次的基数赌局锁死。</p><footer>—— 据 Selinger et al. 优化在路径选择之前；Ramakrishnan and Gehrke；PostgreSQL / SQL 标准对 prepared statement 的整理</footer></div><p><a href="/cs/connection-pooling">上一课</a>让同一后端反复服务请求。本课不调池大小。缺口是语句路径：文本 SQL 每次解析、分析、优化代价不低。预编译（prepared statement）把解析与（可选）计划钉在会话或全局缓存里，执行只传绑定参数。查询语言进阶在此收口，下一单元才回依赖理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 <a href="/cs/query-plan">查询计划</a> 假定一次优化。OLTP 同一条 <code>WHERE id = $1</code> 每秒成千上万次，重复优化浪费 CPU，也增加锁在解析器上的时间。预编译：<code>PREPARE</code> 得到句柄；<code>EXECUTE</code> 带参数。缺口是<strong>计划是否在绑参数之前就定死</strong>：参数未到时只能用平均选择率；第一次执行的参数若极特殊，缓存计划可能永远选错路径。</p><p>绑定窥视（bind peeking）：用第一次（或每次）参数再优化。通用计划：不看参数。两种策略在倾斜数据上行为相反。本课钉权衡，不把某一产品默认当理论。</p><p><span class="marginnote">SQL 注入：预编译把参数当数据不进解析器，是正确性与安全的同一机制。ORM 若退回拼字符串，池与预编译都救不了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端：参数化 API，禁止拼值。服务端：会话级准备语句，或全局计划缓存按文本+常量折叠后的形状索引。失效：统计更新、索引增减、模式版本（上一课迁移）必须丢缓存。</p><p>与存储过程：过程体内语句同样走缓存；过程本身是另一层句柄。本课不把二者当成一种对象。</p>',10)),(e(),s(E,null,{default:t(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22SQL%20%E6%96%87%E6%9C%AC%22%5D%20--%3E%20PARSE%5B%22%E8%A7%A3%E6%9E%90%20%2F%20%E5%88%86%E6%9E%90%22%5D%0A%20%20PARSE%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E6%88%90%E8%AE%A1%E5%88%92%22%5D%0A%20%20OPT%20--%3E%20CACHE%5B%22%E8%AE%A1%E5%88%92%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20EXEC%5B%22%E7%BB%91%E5%AE%9A%E5%8F%82%E6%95%B0%E6%89%A7%E8%A1%8C%22%5D%0A%20%20STAT%5B%22%E7%BB%9F%E8%AE%A1%20%2F%20%E6%A8%A1%E5%BC%8F%E5%8F%98%E6%9B%B4%22%5D%20--%3E%20INV%5B%22%E5%A4%B1%E6%95%88%22%5D%0A%20%20INV%20--%3E%20OPT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价模型仍用 <a href="/cs/histogram-card">直方图</a>。缓存命中跳过搜索，等于假设「形状不变则计划不变」。倾斜、数据涨一个数量级、参数从「一个 id」变成「半个表的范围」，假设破裂，表现为突然变慢——后课计划回归专门命名。本课只要求：缓存是性能合同，不是语义合同；结果应与每次重优化相同（忽略计划导致的超时差异）。</p><p>内存：每个缓存计划占解析树与算子树。无界缓存会胀。LRU 淘汰与池的后端寿命耦合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Selinger 动态规划如何搜连接顺序——那是下一单元第一课。也不讲学习型优化器。依赖理论单元从 Armstrong 公理重开模式侧，与本课执行侧分开。</p><p>后课默认：OLTP 用参数化语句；计划可缓存；统计与模式变必须能失效。查询语言进阶结束：聚合到计划缓存是「把 SQL 用完整」。</p><p>通用计划与窥视计划的选择，要按数据倾斜显式想，不能只开缓存开关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预编译分离解析/优化与执行；参数化同时防注入。</li><li>缓存计划摊优化，也可能锁死坏估计；统计变更要失效。</li><li>下一单元依赖理论：从 Armstrong 公理把主干范式课背后的推导补全。</li><li>出处：Selinger et al.；Ramakrishnan and Gehrke；SQL prepared statements。</li></ul>',9))])}const f=n(c,[["render",h]]);export{S as __pageData,f as default};
